const payload=[{"path":"static/visit_record.mjs","bytes":7525,"sha256":"feab129527c2b596cbc64f26c59901dbfb878bf590d3927f1819af4edc1a3b2f","gitBlob":"2b5b37e3d4a227e00a5b0052a962d13512b53e48","content":"/** Local, explicit visit outcomes bound to original saved-week occurrences. */\nimport { readWeekFile } from \"./week_file.mjs\";\nimport { calendarWeek } from \"./week_plan.mjs\";\n\nexport const VISIT_RECORD_FORMAT = \"tastetable.visit-record.v1\";\nexport const VISIT_RECORD_LIMITS = Object.freeze({\n  sourceBytes: 2 * 1024 * 1024, fileBytes: 8 * 1024 * 1024,\n  occurrences: 100, nameCodePoints: 512, noteCodePoints: 4000,\n});\nconst outcomes = new Set([\"unrecorded\", \"went\", \"did_not_go\"]);\nconst utf8 = new TextEncoder();\nconst fail = (condition, message) => { if (!condition) throw new TypeError(message); };\n\nfunction fields(value, expected, label) {\n  fail(value !== null && typeof value === \"object\" && !Array.isArray(value)\n    && [Object.prototype, null].includes(Object.getPrototypeOf(value)),\n  label + \" must be a plain record.\");\n  const keys = Reflect.ownKeys(value);\n  fail(keys.length === expected.length && expected.every(key => keys.includes(key))\n    && expected.every(key => Object.hasOwn(Object.getOwnPropertyDescriptor(value, key), \"value\")),\n  label + \" has missing or unsupported fields.\");\n}\nfunction unicode(text, label) {\n  fail(typeof text === \"string\" && text.isWellFormed(), label + \" must contain valid Unicode text.\");\n}\nfunction boundedText(text, maxBytes, label) {\n  unicode(text, label);\n  fail(utf8.encode(text).byteLength <= maxBytes, label + \" is too large.\");\n}\nfunction name(value) {\n  unicode(value, \"Source name\");\n  fail(value.trim().length > 0 && [...value].length <= VISIT_RECORD_LIMITS.nameCodePoints\n    && !/[\\u0000-\\u001f\\u007f]/u.test(value),\n  \"Use a nonblank source name of at most 512 characters, without control characters.\");\n  return value;\n}\nfunction note(value) {\n  unicode(value, \"Visit note\");\n  fail([...value].length <= VISIT_RECORD_LIMITS.noteCodePoints\n    && !/[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]/u.test(value),\n  \"Use at most 4,000 characters in a note; only tabs and line breaks are allowed as control characters.\");\n  return value;\n}\nfunction visitDate(value) {\n  if (value === null) return null;\n  fail(typeof value === \"string\" && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)\n    && value.slice(0, 4) !== \"0000\", \"Use a real date in YYYY-MM-DD form, within years 0001–9999.\");\n  const parsed = new Date(value + \"T12:00:00.000Z\");\n  fail(Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value,\n    \"Use a real calendar date in YYYY-MM-DD form.\");\n  return value;\n}\nfunction timestamp(value) {\n  fail(typeof value === \"string\", \"The visit record needs a saved timestamp.\");\n  const date = new Date(value);\n  fail(Number.isFinite(date.getTime()) && date.toISOString() === value,\n    \"The visit record needs a canonical saved timestamp.\");\n  return value;\n}\nfunction freeze(value) {\n  if (value && typeof value === \"object\" && !Object.isFrozen(value)) {\n    Object.values(value).forEach(freeze);\n    Object.freeze(value);\n  }\n  return value;\n}\nfunction source(value) {\n  fields(value, [\"name\", \"weekText\"], \"Source\");\n  name(value.name);\n  boundedText(value.weekText, VISIT_RECORD_LIMITS.sourceBytes, \"Original saved week\");\n  const saved = readWeekFile(value.weekText);\n  fail(saved.state.picks.length <= VISIT_RECORD_LIMITS.occurrences,\n    \"Choose a saved week with at most 100 original picks.\");\n  return saved;\n}\nfunction entry(value) {\n  fields(value, [\"key\", \"outcome\", \"date\", \"note\"], \"Visit\");\n  fail(typeof value.key === \"string\" && outcomes.has(value.outcome), \"The visit has an unsupported key or outcome.\");\n  return { key: value.key, outcome: value.outcome, date: visitDate(value.date), note: note(value.note) };\n}\nfunction normalize(record) {\n  fields(record, [\"source\", \"visits\"], \"Visit record\");\n  const saved = source(record.source), keys = saved.state.picks.map(pick => pick.key);\n  fail(Array.isArray(record.visits) && record.visits.length === keys.length,\n    \"Include every original pick exactly once.\");\n  const entries = new Map();\n  for (const raw of record.visits) {\n    const value = entry(raw);\n    fail(keys.includes(value.key) && !entries.has(value.key), \"The visit record has an unknown or repeated pick.\");\n    entries.set(value.key, value);\n  }\n  const normalized = freeze({\n    source: { name: record.source.name, weekText: record.source.weekText },\n    visits: keys.map(key => entries.get(key)),\n  });\n  return { record: normalized, saved };\n}\n\n/** Preserve the complete source text; planned days never imply an outcome or actual date. */\nexport function createVisitRecord(weekText, sourceName) {\n  const original = { name: sourceName, weekText }, saved = source(original);\n  return normalize({ source: original, visits: saved.state.picks.map(({ key }) => ({\n    key, outcome: \"unrecorded\", date: null, note: \"\",\n  })) }).record;\n}\n\n/** Validate the full input before applying a field-specific, immutable change. */\nexport function updateVisitRecord(record, occurrenceKey, patch) {\n  const current = normalize(record).record;\n  fail(patch !== null && typeof patch === \"object\" && !Array.isArray(patch)\n    && [Object.prototype, null].includes(Object.getPrototypeOf(patch)), \"Use a visit-field patch.\");\n  const keys = Reflect.ownKeys(patch);\n  fail(keys.every(key => [\"outcome\", \"date\", \"note\"].includes(key)\n    && Object.hasOwn(Object.getOwnPropertyDescriptor(patch, key), \"value\")), \"The patch contains an unsupported field.\");\n  fail(current.visits.some(visit => visit.key === occurrenceKey), \"Choose an original pick in this record.\");\n  return normalize({\n    source: current.source,\n    visits: current.visits.map(visit => visit.key === occurrenceKey ? { ...visit, ...patch } : visit),\n  }).record;\n}\n\n/** This public projection retains the original complete pick and exact saved arrangement. */\nexport function visitRecordRows(record) {\n  const { record: current, saved } = normalize(record);\n  const dates = Object.fromEntries(calendarWeek(saved.state.weekStart).map(row => [row.day, row.date]));\n  return freeze(saved.state.picks.map((original, index) => ({\n    key: original.key, originalDay: original.originalDay,\n    plannedDay: saved.state.assignments[original.key],\n    plannedDate: dates[saved.state.assignments[original.key]] ?? null,\n    pick: structuredClone(original.pick),\n    outcome: current.visits[index].outcome, date: current.visits[index].date,\n    note: current.visits[index].note,\n  })));\n}\n\nexport function makeVisitRecordFile(record, now = new Date()) {\n  const { record: current, saved } = normalize(record);\n  fail(now instanceof Date && Number.isFinite(now.getTime()), \"Use a valid save time.\");\n  const text = JSON.stringify({\n    format: VISIT_RECORD_FORMAT, savedAt: now.toISOString(),\n    source: current.source, visits: current.visits,\n  }, null, 2) + \"\\n\";\n  boundedText(text, VISIT_RECORD_LIMITS.fileBytes, \"Visit record file\");\n  return { filename: `tastetable-visits-${saved.state.weekStart}.json`, text };\n}\n\nexport function readVisitRecord(text) {\n  boundedText(text, VISIT_RECORD_LIMITS.fileBytes, \"Visit record file\");\n  let envelope;\n  try { envelope = JSON.parse(text.replace(/^\\uFEFF/, \"\")); }\n  catch { throw new TypeError(\"Choose a valid JSON visit record.\"); }\n  fields(envelope, [\"format\", \"savedAt\", \"source\", \"visits\"], \"Visit record file\");\n  fail(envelope.format === VISIT_RECORD_FORMAT, \"Choose a TasteTable visit record in the supported v1 format.\");\n  const savedAt = timestamp(envelope.savedAt);\n  const record = normalize({ source: envelope.source, visits: envelope.visits }).record;\n  return Object.freeze({ record, savedAt });\n}\n"},{"path":"static/week_file.mjs","bytes":6642,"sha256":"914291b97250a97f6e09f47e6fed58b607b3b1ed9e4c60e3242ff39546913614","gitBlob":"420ddb8f63fca264dcf97be7147801105696155d","content":"/** Portable, user-opened snapshots of an existing TasteTable week. */\nimport { createWeekPlan, setPickDay } from \"./week_plan.mjs\";\n\nexport const WEEK_FILE_FORMAT = \"tastetable.saved-week.v1\";\n\nconst object = (value) => value !== null && typeof value === \"object\" && !Array.isArray(value);\nconst copy = (value) => structuredClone(value);\nconst same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n\nfunction requireValue(condition, message) {\n  if (!condition) throw new TypeError(message);\n}\n\nfunction timestamp(value) {\n  requireValue(typeof value === \"string\", \"The saved week is missing a valid timestamp.\");\n  const date = new Date(value);\n  requireValue(Number.isFinite(date.getTime()) && date.toISOString() === value,\n    \"The saved week is missing a valid timestamp.\");\n  return value;\n}\n\nfunction readInputs(value) {\n  requireValue(object(value), \"The saved week is missing its original inputs.\");\n  for (const key of [\"cuisines\", \"music\", \"films\", \"constraints\"]) {\n    requireValue(Array.isArray(value[key]) && value[key].every((item) => typeof item === \"string\"),\n      \"The saved week has invalid \" + key + \" inputs.\");\n  }\n  requireValue(typeof value.city === \"string\", \"The saved week has an invalid city input.\");\n  return copy(value);\n}\n\nfunction textFields(value, fields, label) {\n  requireValue(object(value) && fields.every((field) => typeof value[field] === \"string\"),\n    \"The saved response has invalid \" + label + \".\");\n}\n\nfunction readResponse(value) {\n  requireValue(object(value) && object(value.plan), \"The saved week is missing its original response.\");\n  const plan = value.plan;\n  requireValue(Array.isArray(plan.meals) && Array.isArray(plan.notes)\n    && plan.notes.every((note) => typeof note === \"string\") && Array.isArray(plan.rejected),\n  \"The saved response has an incomplete original plan.\");\n  for (const pick of [...plan.meals, ...(plan.outing == null ? [] : [plan.outing])]) {\n    textFields(pick, [\"name\", \"why\", \"entity_id\", \"kind\", \"day\"], \"original pick fields\");\n    requireValue(pick.affinity == null || (typeof pick.affinity === \"number\" && Number.isFinite(pick.affinity)),\n      \"The saved response has an invalid affinity value.\");\n    requireValue(pick.fallback === undefined || typeof pick.fallback === \"boolean\",\n      \"The saved response has an invalid fallback value.\");\n  }\n  requireValue(object(value.llm_only) && Array.isArray(value.llm_only.meals),\n    \"The saved response is missing its original comparison plan.\");\n  for (const pick of [...value.llm_only.meals, value.llm_only.outing]) {\n    textFields(pick, [\"name\", \"why\", \"day\"], \"comparison pick fields\");\n  }\n  // These fields are native numeric counts, including two inherited raw HTML\n  // interpolation sites. A local file must not supply HTML in their place.\n  const counts = [\"picks\", \"with_qloo_entity_id\", \"with_affinity_evidence\", \"constraint_checked\", \"unsafe_candidates_rejected\"];\n  for (const side of [\"grounded\", \"llm_only\"]) {\n    const values = value.comparison?.[side];\n    requireValue(object(values) && counts.every((key) => Number.isSafeInteger(values[key]) && values[key] >= 0),\n      \"The saved response has invalid comparison counts.\");\n  }\n  for (const rejected of plan.rejected) {\n    textFields(rejected, [\"name\"], \"rejected candidate fields\");\n    requireValue(Array.isArray(rejected.failed), \"The saved response has invalid rejected checks.\");\n    for (const check of rejected.failed) textFields(check, [\"constraint\", \"status\", \"reason\"], \"rejected check fields\");\n  }\n  requireValue(Array.isArray(value.trace), \"The saved response is missing its original tool trace.\");\n  for (const entry of value.trace) {\n    textFields(entry, [\"tool\", \"result_summary\"], \"tool trace fields\");\n    // Native decoder recovery deliberately retains null, arrays and scalar\n    // arguments in diagnostics. JSON.stringify + escaping renders them as data.\n    requireValue(Object.hasOwn(entry, \"args\"), \"The saved response is missing tool arguments.\");\n  }\n  return copy(value);\n}\n\nfunction restore(value) {\n  requireValue(object(value) && value.format === WEEK_FILE_FORMAT,\n    \"Choose a TasteTable saved-week file in the supported v1 format.\");\n  const receivedAt = timestamp(value.receivedAt);\n  const savedAt = timestamp(value.savedAt);\n  requireValue(value.calendarId === null || (typeof value.calendarId === \"string\" && /^[0-9a-f]{32}$/.test(value.calendarId)),\n    \"The saved week has an invalid calendar identity.\");\n  const inputs = readInputs(value.inputs);\n  requireValue(object(value.week) && object(value.week.assignments),\n    \"The saved week is missing its arrangement.\");\n  const response = readResponse(value.response);\n  let state = createWeekPlan(response, value.week.start);\n  requireValue(state.weekStart === value.week.start,\n    \"The saved week must identify the Monday of its displayed week.\");\n  requireValue(same(inputs.constraints, state.constraints),\n    \"The saved inputs and the original response have different constraints.\");\n  const keys = state.picks.map(({ key }) => key);\n  requireValue(Object.keys(value.week.assignments).length === keys.length\n    && keys.every((key) => Object.hasOwn(value.week.assignments, key)),\n  \"The saved arrangement must include every original pick exactly once.\");\n  for (const key of keys) state = setPickDay(state, key, value.week.assignments[key]);\n  return { response, inputs, state, receivedAt, savedAt, calendarId: value.calendarId };\n}\n\n/** The response is retained whole, including source explanations and tool trace. */\nexport function makeWeekFile({ response, inputs, state, receivedAt, calendarId }, now = new Date()) {\n  const envelope = {\n    format: WEEK_FILE_FORMAT,\n    receivedAt,\n    savedAt: now.toISOString(),\n    calendarId,\n    inputs: copy(inputs),\n    response: copy(response),\n    week: { start: state?.weekStart, assignments: copy(state?.assignments) },\n  };\n  const restored = restore(envelope);\n  requireValue(same(state, restored.state),\n    \"The arranged week no longer matches its original response.\");\n  return {\n    filename: `tastetable-week-${state.weekStart}.json`,\n    text: JSON.stringify(envelope, null, 2) + \"\\n\",\n  };\n}\n\n/** Recreate native immutable state; serialized derived picks are never trusted. */\nexport function readWeekFile(text) {\n  requireValue(typeof text === \"string\", \"The saved week must be a JSON text file.\");\n  let value;\n  try {\n    // A UTF-8 BOM is accepted for ordinary editor/file interoperability.\n    value = JSON.parse(text.replace(/^\\uFEFF/, \"\"));\n  } catch {\n    throw new TypeError(\"This file is not valid JSON. Choose a saved TasteTable week.\");\n  }\n  return restore(value);\n}\n"},{"path":"static/week_plan.mjs","bytes":3913,"sha256":"e739adc10d9ae9ba1cb82c6d800c453e8f7bec53e343e0685adeabe98e6f4809","gitBlob":"8ed28163e0273c510fdd8e6f7c5d1c8476efb862","content":"/** Local scheduling of an existing checked plan. No recommendation or provider calls. */\nexport const DAYS = Object.freeze([\n  \"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\", \"Sunday\",\n]);\n\nfunction freeze(value) {\n  if (value && typeof value === \"object\" && !Object.isFrozen(value)) {\n    Object.values(value).forEach(freeze);\n    Object.freeze(value);\n  }\n  return value;\n}\n\nfunction dateKey(date) {\n  const year = date.getUTCFullYear();\n  if (year < 1 || year > 9999) throw new RangeError(\"Choose a week within years 0001–9999.\");\n  return date.toISOString().slice(0, 10);\n}\n\nfunction parseDate(value) {\n  if (typeof value !== \"string\" || !/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) {\n    throw new RangeError(\"Choose a valid calendar date for your week.\");\n  }\n  const date = new Date(`${value}T12:00:00.000Z`);\n  if (!Number.isFinite(date.getTime()) || dateKey(date) !== value) {\n    throw new RangeError(\"Choose a valid calendar date for your week.\");\n  }\n  return date;\n}\n\n/** Calendar dates use UTC arithmetic so a daylight-saving change cannot skip a day. */\nexport function calendarWeek(anchor) {\n  const date = parseDate(anchor);\n  date.setUTCDate(date.getUTCDate() - (date.getUTCDay() + 6) % 7);\n  return DAYS.map((day) => {\n    const row = Object.freeze({ day, date: dateKey(date) });\n    date.setUTCDate(date.getUTCDate() + 1);\n    return row;\n  });\n}\n\n/** Use the browser's current calendar date, not the UTC date near local midnight. */\nexport function localDate(now = new Date()) {\n  if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {\n    throw new RangeError(\"A valid current date is required.\");\n  }\n  return `${String(now.getFullYear()).padStart(4, \"0\")}-${String(now.getMonth() + 1).padStart(2, \"0\")}-${String(now.getDate()).padStart(2, \"0\")}`;\n}\n\nexport function createWeekPlan(response, anchor = localDate()) {\n  if (!response?.plan || !Array.isArray(response.plan.meals)) {\n    throw new TypeError(\"The response does not contain a weekly plan.\");\n  }\n  const sourcePlan = structuredClone(response.plan);\n  const picks = [...sourcePlan.meals, ...(sourcePlan.outing ? [sourcePlan.outing] : [])]\n    .map((pick, index) => {\n      if (!pick || !DAYS.includes(pick.day) || ![\"restaurant\", \"outing\"].includes(pick.kind)\n          || typeof pick.entity_id !== \"string\" || !pick.entity_id.trim()) {\n        throw new TypeError(\"A suggested pick is missing its source identity, kind or day.\");\n      }\n      return { key: `pick-${index}`, originalDay: pick.day, pick };\n    });\n  return freeze({\n    weekStart: calendarWeek(anchor)[0].date,\n    sourceMode: response.mock === true ? \"mock\" : response.mock === false ? \"live\" : \"unknown\",\n    constraints: structuredClone(response.comparison?.constraints ?? []),\n    sourcePlan,\n    picks,\n    assignments: Object.fromEntries(picks.map(({ key, originalDay }) => [key, originalDay])),\n  });\n}\n\nexport function setWeek(state, anchor) {\n  return freeze({ ...state, weekStart: calendarWeek(anchor)[0].date });\n}\n\n/** Multiple checked picks may share a day; no pick is duplicated or displaced. */\nexport function setPickDay(state, key, day) {\n  if (!state.picks.some((pick) => pick.key === key)) throw new RangeError(\"Unknown suggested pick.\");\n  if (day !== null && !DAYS.includes(day)) throw new RangeError(\"Choose a weekday or leave this pick off the week.\");\n  return freeze({ ...state, assignments: { ...state.assignments, [key]: day } });\n}\n\nexport function resetDays(state) {\n  return freeze({\n    ...state,\n    assignments: Object.fromEntries(state.picks.map(({ key, originalDay }) => [key, originalDay])),\n  });\n}\n\nexport function weekRows(state) {\n  return calendarWeek(state.weekStart).map((row) => ({\n    ...row, picks: state.picks.filter(({ key }) => state.assignments[key] === row.day),\n  }));\n}\n\nexport function offWeekPicks(state) {\n  return state.picks.filter(({ key }) => state.assignments[key] === null);\n}\n"},{"path":"static/visit_record_compare.mjs","bytes":5264,"sha256":"3db538f048db2b7239b95c1e6e8d180701113a73fc77723e4cf68a85bc721275","gitBlob":"83de5285cfc48c77be44f24bea2729fefd591d7d","content":"/** Read-only differences between two admitted copies of one original visit record. */\nimport { readVisitRecord, visitRecordRows } from \"./visit_record.mjs\";\nimport { readWeekFile } from \"./week_file.mjs\";\n\nconst FIELD_ORDER = Object.freeze([\"outcome\", \"date\", \"note\"]);\n\nfunction freeze(value) {\n  if (value && typeof value === \"object\" && !Object.isFrozen(value)) {\n    Object.values(value).forEach(freeze);\n    Object.freeze(value);\n  }\n  return value;\n}\nfunction fields(row) {\n  return { outcome: row.outcome, date: row.date, note: row.note };\n}\n\n/** Roles follow the caller; save timestamps do not establish chronology or authority. */\nexport function compareVisitRecords(beforeText, afterText) {\n  const before = readVisitRecord(beforeText);\n  const after = readVisitRecord(afterText);\n  if (before.record.source.weekText !== after.record.source.weekText) {\n    throw new TypeError(\"Choose two visit records made from the same exact original saved-week file, including its formatting.\");\n  }\n  const weekText = before.record.source.weekText;\n  const saved = readWeekFile(weekText);\n  const left = visitRecordRows(before.record);\n  const right = visitRecordRows(after.record);\n  const counts = {\n    total: left.length, changed: 0, unchanged: 0,\n    outcomeChanged: 0, dateChanged: 0, noteChanged: 0,\n  };\n  const rows = left.map((row, index) => {\n    const next = right[index];\n    const changedFields = FIELD_ORDER.filter(field => row[field] !== next[field]);\n    counts[changedFields.length ? \"changed\" : \"unchanged\"]++;\n    for (const field of changedFields) counts[field + \"Changed\"]++;\n    return {\n      key: row.key, originalDay: row.originalDay,\n      plannedDay: row.plannedDay, plannedDate: row.plannedDate, pick: row.pick,\n      before: fields(row), after: fields(next), changedFields,\n    };\n  });\n  return freeze({\n    format: \"tastetable.visit-record-comparison.v1\",\n    source: {\n      weekText, weekStart: saved.state.weekStart, sourceMode: saved.state.sourceMode,\n      receivedAt: saved.receivedAt, savedAt: saved.savedAt,\n      constraints: structuredClone(saved.state.constraints),\n    },\n    before: { sourceName: before.record.source.name, savedAt: before.savedAt },\n    after: { sourceName: after.record.source.name, savedAt: after.savedAt },\n    counts, rows,\n  });\n}\n\n// JSON quoting preserves literal data while keeping every field on one report line.\nfunction quote(value) {\n  return JSON.stringify(value).replaceAll(\"\\u2028\", \"\\\\u2028\").replaceAll(\"\\u2029\", \"\\\\u2029\");\n}\n\n/** A change brief, not an editable backup or a fresh verification of the original plan. */\nexport function renderVisitRecordComparisonText(beforeText, afterText) {\n  const result = compareVisitRecords(beforeText, afterText);\n  const { source, counts } = result;\n  const lines = [\n    \"TasteTable visit-record changes\",\n    \"\",\n    \"Before and after are caller-selected roles; saved timestamps do not establish chronology or authority.\",\n    \"Before source: \" + quote(result.before.sourceName),\n    \"Before record saved at: \" + quote(result.before.savedAt),\n    \"After source: \" + quote(result.after.sourceName),\n    \"After record saved at: \" + quote(result.after.savedAt),\n    \"\",\n    \"Common original week: \" + quote(source.weekStart),\n    \"Original source mode: \" + quote(source.sourceMode),\n    \"Original source received at: \" + quote(source.receivedAt),\n    \"Original week saved at: \" + quote(source.savedAt),\n    \"Original requested constraints: \" + source.constraints.map(quote).join(\", \"),\n    \"\",\n    \"Occurrences: \" + counts.total + \"; changed: \" + counts.changed + \"; unchanged: \" + counts.unchanged + \".\",\n    \"Field changes (counts can overlap): outcome \" + counts.outcomeChanged\n      + \"; actual date \" + counts.dateChanged + \"; note \" + counts.noteChanged + \".\",\n  ];\n  if (!counts.changed) lines.push(\"\", \"No visit fields changed.\");\n  for (const row of result.rows) {\n    if (!row.changedFields.length) continue;\n    lines.push(\n      \"\",\n      \"Occurrence \" + quote(row.key) + \": \" + quote(row.pick.name),\n      \"  Original entity ID: \" + quote(row.pick.entity_id),\n      \"  Original kind: \" + quote(row.pick.kind),\n      \"  Original suggested day: \" + quote(row.originalDay),\n      \"  Planned day: \" + quote(row.plannedDay),\n      \"  Planned date: \" + quote(row.plannedDate),\n      \"  Original explanation: \" + quote(row.pick.why),\n      \"  Changed fields: \" + row.changedFields.join(\", \"),\n      \"  Before outcome: \" + quote(row.before.outcome),\n      \"  Before actual date: \" + quote(row.before.date),\n      \"  Before note: \" + quote(row.before.note),\n      \"  After outcome: \" + quote(row.after.outcome),\n      \"  After actual date: \" + quote(row.after.date),\n      \"  After note: \" + quote(row.after.note),\n    );\n  }\n  lines.push(\n    \"\",\n    \"Outcomes, actual dates and notes are independently entered values; planned dates do not imply attendance.\",\n    \"Original source labels and explanations are retained; checks were not rerun. Mock sources are fictional demonstrations.\",\n    \"This brief does not replace either record, confirm a venue or update a calendar.\",\n    \"Keep both original JSON files as the editable records; unchanged occurrences are counted rather than expanded here.\",\n    \"\",\n  );\n  return lines.join(\"\\n\");\n}\n"},{"path":"docs/receiving/visit-record-comparison-234cae4aee53/peer-recovery/model-oracle-v1.mjs","bytes":14260,"sha256":"d507a0e78b53019bbda10ecc55b51832eb9da4b173038879cdfc49f2b5e9190c","gitBlob":"1dcf2b4e10b05560960063dec0d263a42c69cb4e","content":"import assert from 'node:assert/strict';\nimport {createHash} from 'node:crypto';\nconst digest = text => createHash('sha256').update(text).digest('hex');\nconst copy = value => structuredClone(value);\nconst quote = value => JSON.stringify(value).replace(/\\u2028/g,'\\\\u2028').replace(/\\u2029/g,'\\\\u2029');\nconst fields = ['outcome','date','note'];\nconst baseCounts = {total:5,changed:4,unchanged:1,outcomeChanged:2,dateChanged:2,noteChanged:2};\nconst beforeName = 'Earlier \"caption\"\\u2028', afterName = 'Later 表\\u2029';\nconst beforeSaved = '2030-01-01T00:00:00.000Z', afterSaved = '2020-01-01T00:00:00.000Z';\nconst sourceReceived = '2026-10-01T12:00:00.000Z', sourceSaved = '2026-10-02T12:00:00.000Z';\nconst literal = [\n{key:'pick-0',originalDay:'Monday',plannedDay:'Wednesday',plannedDate:'2026-10-07',before:{outcome:'unrecorded',date:null,note:''},after:{outcome:'went',date:'2026-10-04',note:' dinner\\t🍜\\nLiteral <script>&\"  '},changedFields:['outcome','date','note']},\n{key:'pick-1',originalDay:'Tuesday',plannedDay:'Monday',plannedDate:'2026-10-05',before:{outcome:'went',date:'2026-10-07',note:'same'},after:{outcome:'went',date:'2026-10-07',note:'same'},changedFields:[]},\n{key:'pick-2',originalDay:'Wednesday',plannedDay:null,plannedDate:null,before:{outcome:'did_not_go',date:null,note:'cancelled'},after:{outcome:'unrecorded',date:null,note:'cancelled'},changedFields:['outcome']},\n{key:'pick-3',originalDay:'Thursday',plannedDay:'Sunday',plannedDate:'2026-10-11',before:{outcome:'went',date:'2026-10-11',note:'unchanged-note'},after:{outcome:'went',date:null,note:'unchanged-note'},changedFields:['date']},\n{key:'pick-4',originalDay:'Saturday',plannedDay:'Friday',plannedDate:'2026-10-09',before:{outcome:'unrecorded',date:null,note:'e\\u0301\\r\\n'},after:{outcome:'unrecorded',date:null,note:'é\\n'},changedFields:['note']},\n];\nfunction deepFrozen(value) {\n  if (value && typeof value === 'object') {\n    assert.equal(Object.isFrozen(value),true);\n    for (const child of Object.values(value)) deepFrozen(child);\n  }\n}\nexport function makeIndependentFixture({record,file,plan}, count=5) {\n  const counts={picks:count,with_qloo_entity_id:count,with_affinity_evidence:0,constraint_checked:count,unsafe_candidates_rejected:0};\n  const picks = Array.from({length:count},(_,index)=>({\n    name:index<2?'Café \"Loop\"':index===4?'Park\\u2029heading':'Venue '+index,\n    why:index===1?'UNCHANGED_ONLY_EXPLANATION_91e8':index===0?'First\\nSOURCE HEADING\\u2028 <b>&\"':'Reason '+index,\n    entity_id:index<2?'venue:same':'venue:'+index,kind:index===4?'outing':'restaurant',\n    day:['Monday','Tuesday','Wednesday','Thursday','Saturday'][index%5],\n    unknown:{rank:index,evidence:[null,false,{literal:'source-'+index}]} ,\n  }));\n  const response={mock:true,plan:{meals:picks.filter(p=>p.kind==='restaurant'),outing:picks.find(p=>p.kind==='outing')??null,notes:['Original note'],rejected:[]},\n    llm_only:{meals:[],outing:{name:'comparison only',why:'not a native pick',day:'Sunday'}},\n    comparison:{constraints:['literal constraint'],grounded:counts,llm_only:counts},trace:[{tool:'fixture',args:null,result_summary:'synthetic original'}]};\n  // For large cases keep the native order purely meal-based; the five-row case explicitly exercises its last outing.\n  if(count!==5){for(const p of picks)p.kind='restaurant';response.plan.meals=picks;response.plan.outing=null;}\n  let state=plan.createWeekPlan(response,'2026-10-05');\n  if(count===5){for(const [i,day] of ['Wednesday','Monday',null,'Sunday','Friday'].entries())state=plan.setPickDay(state,'pick-'+i,day);}\n  const original=file.makeWeekFile({response,inputs:{city:'Fixture city',cuisines:['x'],music:[],films:[],constraints:['literal constraint'],unknownInput:{retained:true}},state,receivedAt:sourceReceived,calendarId:null},new Date(sourceSaved)).text;\n  const empty=record.createVisitRecord(original,beforeName);\n  function saved(triples,name=beforeName,when=beforeSaved,reorder=false){\n    let value=record.createVisitRecord(original,name);\n    for(let i=0;i<triples.length;i++)value=record.updateVisitRecord(value,'pick-'+i,triples[i]);\n    const text=record.makeVisitRecordFile(value,new Date(when)).text;\n    if(!reorder)return text;\n    const parsed=JSON.parse(text);parsed.visits.reverse();return JSON.stringify(parsed)+'\\n';\n  }\n  return {original,picks,response,state,empty,saved};\n}\nexport async function receive({api,record,file,plan}) {\n  const groups=[],calls={compare:0,render:0},checks=[];\n  const compare=(a,b)=>{calls.compare++;return api.compareVisitRecords(a,b);};\n  const render=(a,b)=>{calls.render++;return api.renderVisitRecordComparisonText(a,b);};\n  const fixture=makeIndependentFixture({record,file,plan});\n  const a=fixture.saved(literal.map(x=>x.before),beforeName,beforeSaved,true);\n  const b=fixture.saved(literal.map(x=>x.after),afterName,afterSaved,true);\n  const pins={before:digest(a),after:digest(b),week:digest(fixture.original)};\n  const expectedRows=literal.map((row,index)=>({...copy(row),pick:copy(fixture.picks[index])}));\n  const expected={format:'tastetable.visit-record-comparison.v1',\n    source:{weekText:fixture.original,weekStart:'2026-10-05',sourceMode:'mock',receivedAt:sourceReceived,savedAt:sourceSaved,constraints:['literal constraint']},\n    before:{sourceName:beforeName,savedAt:beforeSaved},after:{sourceName:afterName,savedAt:afterSaved},counts:baseCounts,rows:expectedRows};\n  const result=compare(a,b);assert.deepEqual(result,expected);deepFrozen(result);\n  assert.equal(Object.getPrototypeOf(result),Object.prototype);\n  assert.equal(result.rows[0].pick.entity_id,result.rows[1].pick.entity_id);\n  assert.notEqual(result.rows[0].key,result.rows[1].key);\n  assert.throws(()=>{result.rows[0].pick.unknown.rank=123;},TypeError);\n  assert.deepEqual(compare(a,b),expected);\n  groups.push('literal five-row complete result, duplicate occurrences, native source order and recursive immutability');\n  const inverse=compare(b,a);const swapped=copy(expected);swapped.before=expected.after;swapped.after=expected.before;\n  swapped.rows=expectedRows.map(row=>({...copy(row),before:copy(row.after),after:copy(row.before)}));\n  assert.deepEqual(inverse,swapped);\n  const metadata=fixture.saved(literal.map(x=>x.before),afterName,afterSaved);\n  const onlyMeta=compare(a,metadata);assert.deepEqual(onlyMeta.counts,{total:5,changed:0,unchanged:5,outcomeChanged:0,dateChanged:0,noteChanged:0});\n  assert.deepEqual(onlyMeta.before,expected.before);assert.deepEqual(onlyMeta.after,expected.after);\n  assert.ok(onlyMeta.rows.every(row=>row.changedFields.length===0));\n  const bomEnvelope=compare('\\uFEFF'+a,b);assert.deepEqual(bomEnvelope,result);\n  groups.push('caller reversal, metadata-only differences and outer-envelope BOM without chronology promotion');\n  const single=makeIndependentFixture({record,file,plan},1);\n  const pairs=[\n    [{outcome:'went',date:'2024-02-29',note:'kept'},{outcome:'did_not_go',date:'2024-02-29',note:'kept'},['outcome']],\n    [{outcome:'unrecorded',date:null,note:''},{outcome:'unrecorded',date:'0001-01-01',note:''},['date']],\n    [{outcome:'did_not_go',date:'9999-12-31',note:'keep'},{outcome:'did_not_go',date:null,note:'keep'},['date']],\n    [{outcome:'unrecorded',date:null,note:'e\\u0301'},{outcome:'unrecorded',date:null,note:'é'},['note']],\n    [{outcome:'unrecorded',date:null,note:'a\\r\\nb'},{outcome:'unrecorded',date:null,note:'a\\nb'},['note']],\n    [{outcome:'unrecorded',date:null,note:'a\\rb'},{outcome:'unrecorded',date:null,note:'a\\r\\nb'},['note']],\n    [{outcome:'went',date:'2026-10-05',note:'clear'},{outcome:'unrecorded',date:null,note:''},fields],\n  ];\n  for(const [oldValue,newValue,changedFields] of pairs){\n    const r=compare(single.saved([oldValue]),single.saved([newValue]));\n    assert.deepEqual(r.rows[0].before,oldValue);assert.deepEqual(r.rows[0].after,newValue);\n    assert.deepEqual(r.rows[0].changedFields,changedFields);\n    assert.deepEqual(r.counts,{total:1,changed:1,unchanged:0,outcomeChanged:+changedFields.includes('outcome'),dateChanged:+changedFields.includes('date'),noteChanged:+changedFields.includes('note')});\n  }\n  groups.push('independent field transitions, clears, date boundaries and exact Unicode/CR/CRLF/LF comparison');\n  const variantWeek=change=>{const parsed=JSON.parse(fixture.original);change(parsed);return JSON.stringify(parsed,null,2)+'\\n';};\n  const variants=[\n    ['trailing whitespace',fixture.original+' '],\n    ['source BOM','\\uFEFF'+fixture.original],\n    ['CRLF',fixture.original.replace(/\\n/g,'\\r\\n')],\n    ['arrangement',variantWeek(v=>{v.week.assignments['pick-0']='Monday';})],\n    ['input',variantWeek(v=>{v.inputs.city='Elsewhere';})],\n    ['unknown response metadata',variantWeek(v=>{v.response.plan.meals[0].unknown.rank=99;})],\n    ['source saved timestamp',variantWeek(v=>{v.savedAt='2026-10-03T12:00:00.000Z';})],\n    ['source received timestamp',variantWeek(v=>{v.receivedAt='2026-09-30T12:00:00.000Z';})],\n  ];\n  for(const [name,week] of variants){\n    file.readWeekFile(week);\n    const alternate=record.makeVisitRecordFile(record.createVisitRecord(week,'different original'),new Date(afterSaved)).text;\n    for(const pair of [[a,alternate],[alternate,a]])assert.throws(()=>compare(...pair),error=>error instanceof TypeError&&/same|original|source/i.test(error.message),name);\n    assert.throws(()=>render(a,alternate),TypeError,name);\n  }\n  groups.push('eight independently admitted different originals refused in both caller orders');\n  const zero=makeIndependentFixture({record,file,plan},0);\n  const z=compare(zero.saved([]),zero.saved([],afterName,afterSaved));\n  assert.deepEqual(z.rows,[]);assert.deepEqual(z.counts,{total:0,changed:0,unchanged:0,outcomeChanged:0,dateChanged:0,noteChanged:0});\n  const hundred=makeIndependentFixture({record,file,plan},100);\n  const blanks=Array.from({length:100},()=>({outcome:'unrecorded',date:null,note:''}));\n  const changed=copy(blanks);changed[99]={outcome:'did_not_go',date:null,note:'last only'};\n  const hr=compare(hundred.saved(blanks),hundred.saved(changed));\n  assert.equal(hr.rows.length,100);assert.deepEqual(hr.rows.map(x=>x.key),Array.from({length:100},(_,i)=>'pick-'+i));\n  assert.deepEqual(hr.counts,{total:100,changed:1,unchanged:99,outcomeChanged:1,dateChanged:0,noteChanged:1});\n  assert.deepEqual(hr.rows[99].after,changed[99]);assert.throws(()=>makeIndependentFixture({record,file,plan},101),TypeError);\n  groups.push('zero and100 original occurrences, explicit unrecorded values and101-producer refusal');\n  const altered=fn=>{const value=JSON.parse(a);fn(value);return JSON.stringify(value)+'\\n';};\n  const bad=[\n    ['nonstring',null],['JSON','{'],['format',altered(v=>{v.format='other';})],\n    ['noncanonical timestamp',altered(v=>{v.savedAt='2026-01-01';})],\n    ['unknown envelope field',altered(v=>{v.extra=true;})],\n    ['missing visit',altered(v=>{v.visits.pop();})],\n    ['repeated key',altered(v=>{v.visits[0].key=v.visits[1].key;})],\n    ['unknown key',altered(v=>{v.visits[0].key='pick-999';})],\n    ['outcome',altered(v=>{v.visits[0].outcome='assumed';})],\n    ['impossible date',altered(v=>{v.visits[0].date='2025-02-29';})],\n    ['note control',altered(v=>{v.visits[0].note='\\u0000';})],\n    ['lone surrogate',altered(v=>{v.visits[0].note='\\ud800';})],\n    ['embedded invalid week',altered(v=>{v.source.weekText='{}';})],\n    ['extra visit field',altered(v=>{v.visits[0].more='not admitted';})],\n    ['invalid source name',altered(v=>{v.source.name='bad\\nname';})],\n  ];\n  for(const [name,text] of bad){\n    let originalError;try{record.readVisitRecord(text);}catch(error){originalError=error;}\n    assert.ok(originalError,name+' must independently refuse');\n    for(const pair of [[text,b],[a,text]]){\n      assert.throws(()=>compare(...pair),error=>error.constructor===originalError.constructor&&error.message===originalError.message,name);\n      assert.throws(()=>render(...pair),error=>error.constructor===originalError.constructor&&error.message===originalError.message,name);\n    }\n  }\n  groups.push('fifteen complete-record refusals preserve native admission on both API sides and renderer');\n  const report=render(a,b);assert.equal(typeof report,'string');assert.ok(report.endsWith('\\n'));\n  for(const value of [beforeName,afterName,beforeSaved,afterSaved,'mock','2026-10-05',sourceReceived,sourceSaved])assert.ok(report.includes(quote(value)),'quoted metadata '+quote(value));\n  for(const row of expectedRows.filter(row=>row.changedFields.length)){\n    for(const value of [row.key,row.pick.name,row.pick.entity_id,row.pick.why,row.plannedDate,...fields.map(field=>row.before[field]),...fields.map(field=>row.after[field])])assert.ok(report.includes(quote(value)),'quoted changed content '+quote(value));\n  }\n  assert.ok(!report.includes('UNCHANGED_ONLY_EXPLANATION_91e8'));\n  assert.ok(!report.includes('\\u2028')&&!report.includes('\\u2029'));\n  assert.ok(!report.includes('\\nSOURCE HEADING'));\n  assert.ok(!report.includes('\\nLiteral <script>'));\n  assert.match(report,/before/i);assert.match(report,/after/i);\n  for(const field of fields)assert.match(report,new RegExp(field+'[^\\\\n]*2|2[^\\\\n]*'+field,'i'));\n  const unchangedReport=render(a,metadata);assert.match(unchangedReport,/(?:no|zero|0)[^\\n]*chang|chang[^\\n]*(?:no|zero|0)/i);\n  assert.ok(!unchangedReport.includes('UNCHANGED_ONLY_EXPLANATION_91e8'));\n  const emptyReport=render(zero.saved([]),zero.saved([]));assert.match(emptyReport,/(?:no|zero|0)[^\\n]*chang|chang[^\\n]*(?:no|zero|0)/i);\n  groups.push('literal JSON-quoted report, separator/injection controls, complete changed triples and explicit no changes');\n  assert.deepEqual({before:digest(a),after:digest(b),week:digest(fixture.original)},pins);\n  checks.push({literalCounts:result.counts,sourcePins:pins,refusals:bad.length,identityVariants:variants.length,fieldPairs:pairs.length,maximumRows:100,reportBytes:Buffer.byteLength(report),reportSha256:digest(report)});\n  return {format:'tastetable-visit-comparison-peer/1',pass:true,node:process.version,platform:process.platform,groups,calls,checks,\n    boundary:'Exact module source via declared in-memory path loader. No ordinary-file CLI admission, browser or Actions execution.',\n    fixtures:{before:a,after:b,commonWeek:fixture.original,report,unchangedReport,emptyReport}};\n}\n"},{"path":"tests/test_visit_record_compare_oracle.mjs","bytes":2815,"sha256":"cfd689bcf71e750d7a1268b229c3cfebdb716ae8d045420a0bd0484d7756d905","gitBlob":"829bc786ad5b375e7471261f5d74b273047cdcd6","content":"/**\n * New maintained adapter for the unchanged independent oracle by\n * estate-234cae4aee53 / repo_delivery. This is not the lost authored model test.\n */\nimport test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { readFileSync } from \"node:fs\";\nimport * as comparison from \"../static/visit_record_compare.mjs\";\nimport * as record from \"../static/visit_record.mjs\";\nimport * as file from \"../static/week_file.mjs\";\nimport * as plan from \"../static/week_plan.mjs\";\nimport { receive } from \"../docs/receiving/visit-record-comparison-234cae4aee53/peer-recovery/model-oracle-v1.mjs\";\n\nconst ORACLE_SHA256 = \"d507a0e78b53019bbda10ecc55b51832eb9da4b173038879cdfc49f2b5e9190c\";\nconst EXPECTED_GROUPS = [\n  \"literal five-row complete result, duplicate occurrences, native source order and recursive immutability\",\n  \"caller reversal, metadata-only differences and outer-envelope BOM without chronology promotion\",\n  \"independent field transitions, clears, date boundaries and exact Unicode/CR/CRLF/LF comparison\",\n  \"eight independently admitted different originals refused in both caller orders\",\n  \"zero and100 original occurrences, explicit unrecorded values and101-producer refusal\",\n  \"fifteen complete-record refusals preserve native admission on both API sides and renderer\",\n  \"literal JSON-quoted report, separator/injection controls, complete changed triples and explicit no changes\"\n];\nconst oracleUrl = new URL(\n  \"../docs/receiving/visit-record-comparison-234cae4aee53/peer-recovery/model-oracle-v1.mjs\",\n  import.meta.url,\n);\nconst oracleHash = () => createHash(\"sha256\").update(readFileSync(oracleUrl)).digest(\"hex\");\n\n// Seven oracle groups execute inside one native node:test case.\ntest(\"visit-record comparison satisfies the frozen independent oracle\", async t => {\n  const oracleBefore = oracleHash();\n  assert.equal(oracleBefore, ORACLE_SHA256, \"The attributed historical oracle must remain byte-exact.\");\n  const result = await receive({ api: comparison, record, file, plan });\n  const oracleAfter = oracleHash();\n  assert.equal(oracleAfter, ORACLE_SHA256, \"The oracle file must remain unchanged after receiving.\");\n  assert.equal(result.format, \"tastetable-visit-comparison-peer/1\");\n  assert.equal(result.pass, true);\n  assert.deepEqual(result.groups, EXPECTED_GROUPS);\n  assert.deepEqual(result.calls, { compare: 60, render: 41 });\n\n  // The oracle's returned boundary string describes its historical loader run.\n  // Do not emit or adopt that stale label for this ordinary-import adapter.\n  t.diagnostic(JSON.stringify({\n    adapter: \"new maintained test using ordinary module imports\",\n    oracle: { before: oracleBefore, after: oracleAfter },\n    groups: result.groups,\n    calls: result.calls,\n    checks: result.checks,\n  }));\n});\n"}];
const collector="import fs from \"node:fs\";\nimport { resolve, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\nimport { createHash } from \"node:crypto\";\nimport { spawnSync } from \"node:child_process\";\nimport { gzipSync } from \"node:zlib\";\nimport assert from \"node:assert/strict\";\n\nconst root = resolve(process.argv[2] || \"\");\nconst ownedRoot = \"/dev/shm/tastetable-model-stock-234cae4aee53\";\nassert.equal(root, ownedRoot, \"Only the prepared owned root is admitted.\");\nconst expected = [\n  {\n    \"path\": \"static/visit_record.mjs\",\n    \"bytes\": 7525,\n    \"sha256\": \"feab129527c2b596cbc64f26c59901dbfb878bf590d3927f1819af4edc1a3b2f\",\n    \"gitBlob\": \"2b5b37e3d4a227e00a5b0052a962d13512b53e48\"\n  },\n  {\n    \"path\": \"static/week_file.mjs\",\n    \"bytes\": 6642,\n    \"sha256\": \"914291b97250a97f6e09f47e6fed58b607b3b1ed9e4c60e3242ff39546913614\",\n    \"gitBlob\": \"420ddb8f63fca264dcf97be7147801105696155d\"\n  },\n  {\n    \"path\": \"static/week_plan.mjs\",\n    \"bytes\": 3913,\n    \"sha256\": \"e739adc10d9ae9ba1cb82c6d800c453e8f7bec53e343e0685adeabe98e6f4809\",\n    \"gitBlob\": \"8ed28163e0273c510fdd8e6f7c5d1c8476efb862\"\n  },\n  {\n    \"path\": \"static/visit_record_compare.mjs\",\n    \"bytes\": 5264,\n    \"sha256\": \"3db538f048db2b7239b95c1e6e8d180701113a73fc77723e4cf68a85bc721275\",\n    \"gitBlob\": \"83de5285cfc48c77be44f24bea2729fefd591d7d\"\n  },\n  {\n    \"path\": \"docs/receiving/visit-record-comparison-234cae4aee53/peer-recovery/model-oracle-v1.mjs\",\n    \"bytes\": 14260,\n    \"sha256\": \"d507a0e78b53019bbda10ecc55b51832eb9da4b173038879cdfc49f2b5e9190c\",\n    \"gitBlob\": \"1dcf2b4e10b05560960063dec0d263a42c69cb4e\"\n  },\n  {\n    \"path\": \"tests/test_visit_record_compare_oracle.mjs\",\n    \"bytes\": 2815,\n    \"sha256\": \"cfd689bcf71e750d7a1268b229c3cfebdb716ae8d045420a0bd0484d7756d905\",\n    \"gitBlob\": \"829bc786ad5b375e7471261f5d74b273047cdcd6\"\n  }\n];\nconst sha = data => createHash(\"sha256\").update(data).digest(\"hex\");\nconst git = data => createHash(\"sha1\").update(Buffer.from(\"blob \" + data.length)).update(Buffer.from([0])).update(data).digest(\"hex\");\nconst inspect = () => expected.map(pin => {\n  try {\n    const path = join(root, pin.path), info = fs.lstatSync(path), bytes = fs.readFileSync(path);\n    return { path: pin.path, bytes: bytes.length, sha256: sha(bytes), gitBlob: git(bytes),\n      mode: info.mode & 0o777, regular: info.isFile(), symbolic: info.isSymbolicLink() };\n  } catch (error) {\n    return { path: pin.path, error: { name: error.name, code: error.code ?? null, message: error.message } };\n  }\n});\nconst matches = items => items.length === expected.length && items.every((item, index) => {\n  const pin = expected[index];\n  return item.path === pin.path && item.bytes === pin.bytes && item.sha256 === pin.sha256\n    && item.gitBlob === pin.gitBlob && item.mode === 0o644 && item.regular && !item.symbolic;\n});\nconst destination = join(root, \"raw-receipt.json.gz\");\nassert.equal(fs.existsSync(destination), false, \"Do not replace an earlier receipt.\");\nconst collector = fs.readFileSync(fileURLToPath(import.meta.url));\nconst sourceManifest = fs.readFileSync(join(root, \"SOURCE.json\"));\nconst receipt = {\n  schema: \"tastetable.root-ordinary-model-receiving/1\",\n  purpose: \"New ordinary-file execution of the new maintained adapter; not recovery of lost historical raw packets.\",\n  root, startedAt: new Date().toISOString(),\n  node: process.version, versions: process.versions, platform: process.platform, arch: process.arch,\n  executable: process.execPath, collectorArgv: process.argv, collectorCwd: process.cwd(),\n  collector: { bytes: collector.length, sha256: sha(collector), gitBlob: git(collector) },\n  sourceManifest: { bytes: sourceManifest.length, sha256: sha(sourceManifest), value: JSON.parse(sourceManifest) },\n  expected, before: inspect(), after: null, process: null, testCounts: null, diagnostic: null,\n  sourceUnchanged: false, accepted: false, failure: null,\n  boundary: \"Six ordinary source files; no loader, filesystem adapter, large CLI input, browser, hosted workflow or installed-client run. Generated oracle fixture values are new values from this invocation, not recovered old physical files.\"\n};\ntry {\n  assert.ok(matches(receipt.before), \"Before-source pins/modes differ.\");\n  const space = fs.statfsSync(root);\n  receipt.freeBytesBefore = space.bavail * space.bsize;\n  assert.ok(receipt.freeBytesBefore >= 32768, \"At least 32 KiB must remain for receipt custody.\");\n  const env = { ...process.env, NO_COLOR: \"1\" };\n  for (const key of [\"NODE_OPTIONS\", \"NODE_COMPILE_CACHE\", \"NODE_V8_COVERAGE\", \"FORCE_COLOR\"]) delete env[key];\n  const args = [\"--test\", \"--test-reporter=tap\", \"--test-concurrency=1\", \"tests/test_visit_record_compare_oracle.mjs\"];\n  const start = new Date().toISOString();\n  const child = spawnSync(process.execPath, args, { cwd: root, env, timeout: 60000, maxBuffer: 1024 * 1024 });\n  const finished = new Date().toISOString();\n  const stream = value => {\n    const bytes = value ?? Buffer.alloc(0);\n    return { bytes: bytes.length, sha256: sha(bytes), base64: bytes.toString(\"base64\"), utf8: bytes.toString(\"utf8\") };\n  };\n  receipt.process = {\n    executable: process.execPath, argv: args, cwd: root, startedAt: start, finishedAt: finished, pid: child.pid ?? null,\n    timeoutMs: 60000, maxBufferBytes: 1024 * 1024,\n    environment: { NO_COLOR: \"1\", NODE_OPTIONS: null, NODE_COMPILE_CACHE: null, NODE_V8_COVERAGE: null, FORCE_COLOR: null },\n    status: child.status, signal: child.signal,\n    error: child.error ? { name: child.error.name, code: child.error.code ?? null, message: child.error.message } : null,\n    stdout: stream(child.stdout), stderr: stream(child.stderr),\n    rawStreamsComplete: !child.error\n  };\n  receipt.after = inspect();\n  receipt.sourceUnchanged = matches(receipt.after) && JSON.stringify(receipt.before) === JSON.stringify(receipt.after);\n  const stdout = receipt.process.stdout.utf8;\n  const counts = {};\n  for (const label of [\"tests\", \"pass\", \"fail\", \"cancelled\", \"skipped\", \"todo\"]) {\n    const found = stdout.match(new RegExp(\"^# \" + label + \" (\\\\d+)\\\\s*$\", \"m\"));\n    counts[label] = found ? Number(found[1]) : null;\n  }\n  receipt.testCounts = counts;\n  const diagnostics = stdout.split(/\\r?\\n/).map(line => line.replace(/^\\s*#\\s?/, \"\"))\n    .filter(line => line.startsWith('{\"adapter\":')).map(line => JSON.parse(line));\n  assert.equal(child.status, 0);\n  assert.equal(child.signal, null);\n  assert.equal(child.error, undefined);\n  assert.equal(receipt.process.stderr.bytes, 0);\n  assert.ok(receipt.process.rawStreamsComplete);\n  assert.ok(receipt.sourceUnchanged);\n  assert.deepEqual(counts, { tests: 1, pass: 1, fail: 0, cancelled: 0, skipped: 0, todo: 0 });\n  assert.equal(diagnostics.length, 1);\n  const diagnostic = diagnostics[0];\n  receipt.diagnostic = diagnostic;\n  assert.equal(diagnostic.adapter, \"new maintained test using ordinary module imports\");\n  assert.equal(diagnostic.groups.length, 7);\n  assert.deepEqual(diagnostic.calls, { compare: 60, render: 41 });\n  assert.equal(diagnostic.oracle.before, expected[4].sha256);\n  assert.equal(diagnostic.oracle.after, expected[4].sha256);\n  assert.equal(diagnostic.checks.length, 1);\n  const check = diagnostic.checks[0];\n  assert.deepEqual(check.literalCounts, { total: 5, changed: 4, unchanged: 1, outcomeChanged: 2, dateChanged: 2, noteChanged: 2 });\n  assert.equal(check.refusals, 15);\n  assert.equal(check.identityVariants, 8);\n  assert.equal(check.fieldPairs, 7);\n  assert.equal(check.maximumRows, 100);\n  receipt.accepted = true;\n} catch (error) {\n  receipt.failure = { name: error.name, code: error.code ?? null, message: error.message, stack: error.stack };\n  if (!receipt.after) receipt.after = inspect();\n}\nreceipt.finishedAt = new Date().toISOString();\nconst raw = Buffer.from(JSON.stringify(receipt, null, 2) + \"\\n\");\nconst gzip = gzipSync(raw, { level: 9 });\nfs.writeFileSync(destination, gzip, { flag: \"wx\", mode: 0o600 });\nassert.equal(sha(fs.readFileSync(destination)), sha(gzip));\nconsole.log(JSON.stringify({\n  accepted: receipt.accepted, testCounts: receipt.testCounts, calls: receipt.diagnostic?.calls ?? null,\n  status: receipt.process?.status ?? null, sourceUnchanged: receipt.sourceUnchanged, failure: receipt.failure,\n  rawBytes: raw.length, rawSha256: sha(raw), gzipBytes: gzip.length, gzipSha256: sha(gzip),\n  destination, rawGzipBase64: gzip.toString(\"base64\")\n}));\nprocess.exitCode = receipt.accepted ? 0 : 1;\n";
const sha=b=>createHash("sha256").update(b).digest("hex");
const git=b=>createHash("sha1").update(Buffer.from("blob "+b.length)).update(Buffer.from([0])).update(b).digest("hex");
const check=(ok,message)=>{if(!ok)throw Error(message);};
const observe=(root,pin)=>{
 const f=path.join(root,pin.path),st=fs.lstatSync(f),b=fs.readFileSync(f);
 check(st.isFile()&&!st.isSymbolicLink(),"Not an ordinary owned source: "+f);
 check(b.length===pin.bytes&&sha(b)===pin.sha256&&git(b)===pin.gitBlob,"Source changed: "+f);
 return{...pin,mode:st.mode&0o777,allocated:st.blocks*512};
};
check(!fs.existsSync(newRoot),"New receiving root already exists.");
check(!fs.existsSync(path.join(oldRoot,"PAYLOAD-RELOCATED.json")),"Relocation record already exists.");
const originalManifest=fs.readFileSync(path.join(oldRoot,"SOURCE.json"));
check(sha(originalManifest)==="5f4a2aa23e9a42fbf4d165182af1eb262e1356017dd8d0c157d4d86e8332bff3","Hull manifest changed.");
const originalRaw=fs.readFileSync(path.join(oldRoot,"raw-receipt.json.gz"));
check(originalRaw.length===4922&&sha(originalRaw)==="872d4051bcbac6e3b25589d4e50145a958e2ec3244ea2ced575218426f9bc820","Original hull receipt changed.");
const allBefore=prior.map(pin=>observe(oldRoot,pin));
const eligible=allBefore.filter(pin=>pin.path!=="courses/convex-hull-explorer.html");
check(eligible.length===13,"Unexpected retirement closure.");
const sourceFiles=payload.map(pin=>{
 const b=Buffer.from(pin.content);
 check(b.length===pin.bytes&&sha(b)===pin.sha256&&git(b)===pin.gitBlob,"Incoming source differs: "+pin.path);
 return{...pin,buffer:b};
});
const collectorBytes=Buffer.from(collector);
check(collectorBytes.length===8362&&git(collectorBytes)==="da879d1036dfa2d36bb9101df86bba703b2b9dfc","Collector differs from pre-execution freeze.");
const space=fs.statfsSync(oldRoot),block=space.bsize,rounded=n=>Math.ceil(n/block)*block;
const relocation={
 schema:"root.source-copy-relocation/1",sourceRoot:oldRoot,
 custodyCommit:"a9c36fed1a0b9ea53d47d916fb6c944b827b9360",custodyTree:"720e366e2a68fade26bde0e17b5a98703a646399",
 sourceManifestSha256:sha(originalManifest),startedAt:new Date().toISOString(),
 reason:"Reuse only exact Git-backed root source copies for the first ordinary TasteTable maintained model run.",
 retained:["SOURCE.json","raw-receipt.json.gz","courses/convex-hull-explorer.html"],
 rawReceiptSha256:sha(originalRaw),nativeOriginalsPreserved:true,retired:[],error:null
};
const planned={...relocation,retired:eligible,finishedAt:new Date().toISOString()};
const manifestDraft={
 schema:"root.tastetable.ordinary-model-source/1",sourceRoot:newRoot,sourceTree:"d6e0891b39e473f0ffa4690944a91d6f155c24ec",
 receivingFreezeTree:"7983de2a790c09c8e54a9dbac8449d4179d6044e",
 stagedAt:new Date().toISOString(),files:payload.map(({content,...pin})=>pin),
 collector:{path:"root-receiver.mjs",bytes:collectorBytes.length,sha256:sha(collectorBytes),gitBlob:git(collectorBytes)},
 relocation:{receiptPath:path.join(oldRoot,"PAYLOAD-RELOCATED.json"),custodyCommit:relocation.custodyCommit,sourceBytes:eligible.reduce((n,x)=>n+x.bytes,0),retiredFiles:13,receiptSha256:"0".repeat(64)},
 qualification:"Source staging only. New maintained model run and external ordinary CLI gate are separate; old raw evidence remains unavailable."
};
const required=sourceFiles.reduce((n,x)=>n+rounded(x.bytes),0)+rounded(collectorBytes.length)+rounded(Buffer.byteLength(JSON.stringify(manifestDraft)+"\n"))+rounded(Buffer.byteLength(JSON.stringify(planned)+"\n"))+32768+4096;
const reclaim=eligible.reduce((n,x)=>n+x.allocated,0),free=space.bavail*space.bsize;
check(free+reclaim>=required,"Capacity guard before retirement: "+JSON.stringify({free,reclaim,required}));
try{
 for(const pin of eligible){observe(oldRoot,pin);fs.unlinkSync(path.join(oldRoot,pin.path));relocation.retired.push(pin);}
}catch(error){relocation.error={name:error.name,code:error.code??null,message:error.message};throw error;}
finally{
 if(relocation.retired.length){
  relocation.finishedAt=new Date().toISOString();
  fs.writeFileSync(path.join(oldRoot,"PAYLOAD-RELOCATED.json"),JSON.stringify(relocation)+"\n",{flag:"wx",mode:0o600});
 }
}
check(relocation.retired.length===13,"Incomplete retirement.");
fs.mkdirSync(newRoot,{mode:0o700});
for(const pin of sourceFiles){
 const f=path.join(newRoot,pin.path);fs.mkdirSync(path.dirname(f),{recursive:true,mode:0o700});
 fs.writeFileSync(f,pin.buffer,{flag:"wx",mode:0o644});fs.chmodSync(f,0o644);
}
fs.writeFileSync(path.join(newRoot,"root-receiver.mjs"),collectorBytes,{flag:"wx",mode:0o644});
fs.chmodSync(path.join(newRoot,"root-receiver.mjs"),0o644);
const relocationBytes=fs.readFileSync(path.join(oldRoot,"PAYLOAD-RELOCATED.json"));
manifestDraft.stagedAt=new Date().toISOString();manifestDraft.relocation.receiptSha256=sha(relocationBytes);
const manifestBytes=Buffer.from(JSON.stringify(manifestDraft)+"\n");
fs.writeFileSync(path.join(newRoot,"SOURCE.json"),manifestBytes,{flag:"wx",mode:0o600});
const staged=payload.map(({content,...pin})=>observe(newRoot,pin));
const remaining=fs.statfsSync(newRoot);
check(remaining.bavail*remaining.bsize>=32768,"Receipt capacity changed after staging.");
check(sha(fs.readFileSync(path.join(oldRoot,"raw-receipt.json.gz")))===sha(originalRaw),"Hull raw receipt changed.");
observe(oldRoot,prior.find(x=>x.path==="courses/convex-hull-explorer.html"));
console.log(JSON.stringify({
 staged:true,sourceRoot:newRoot,files:staged,sourceBytes:staged.reduce((n,x)=>n+x.bytes,0),
 sourceManifestBytes:manifestBytes.length,sourceManifestSha256:sha(manifestBytes),
 collector:{bytes:collectorBytes.length,sha256:sha(collectorBytes),gitBlob:git(collectorBytes)},
 retirement:{count:relocation.retired.length,sourceBytes:relocation.retired.reduce((n,x)=>n+x.bytes,0),allocated:reclaim,receiptBytes:relocationBytes.length,receiptSha256:sha(relocationBytes),retained:relocation.retained},
 freeBytesAfter:remaining.bavail*remaining.bsize,productExecuted:false
}));
